// Truth tables for implication and its variants, plus a direct proof check
public class PropositionalLogic {
    static boolean implies(boolean p, boolean q) {
        return !p || q; // false only when p is true and q is false
    }

    static boolean biconditional(boolean p, boolean q) {
        return p == q;
    }

    static String tf(boolean b) {
        return b ? "T" : "F";
    }

    static String yesNo(boolean b) {
        return b ? "yes" : "no";
    }

    public static void main(String[] args) {
        boolean[] values = {false, true};
        boolean sameAsOr = true, sameAsContra = true, sameAsConverse = true;
        System.out.println("p q | p->q  ~p|q  ~q->~p  q->p  p<->q");
        for (boolean p : values) {
            for (boolean q : values) {
                boolean imp = implies(p, q);
                boolean orForm = !p || q;
                boolean contra = implies(!q, !p);
                boolean converse = implies(q, p);
                // Two formulas are equivalent only if they agree on EVERY row
                sameAsOr &= imp == orForm;
                sameAsContra &= imp == contra;
                sameAsConverse &= imp == converse;
                System.out.println(tf(p) + " " + tf(q) + " |  " + tf(imp) + "     " + tf(orForm) + "      "
                        + tf(contra) + "      " + tf(converse) + "     " + tf(biconditional(p, q)));
            }
        }
        System.out.println("p->q equivalent to ~p|q?            " + yesNo(sameAsOr));
        System.out.println("p->q equivalent to ~q->~p?          " + yesNo(sameAsContra));
        System.out.println("p->q equivalent to converse q->p?   " + yesNo(sameAsConverse));

        // Claim: if n is odd, then n^2 is odd. Test it on many cases first...
        int tested = 0, oddSquares = 0;
        for (int n = 1; n < 100; n += 2) {
            tested++;
            if ((n * n) % 2 == 1) oddSquares++;
        }
        System.out.println("odd n in 1..99 with odd n^2: " + oddSquares + " of " + tested);
        // ...but only an argument that works for every n is a proof
        System.out.println("Direct proof: assume n = 2k+1, then n^2 = 2(2k^2+2k)+1, which is odd.");
    }
}

