import java.util.List;

// Atomic propositions get their truth values from facts; compound ones from connectives
public class PropositionsDemo {
    record Statement(String formula, String english, boolean value) {}

    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        // Each atomic proposition is a declarative sentence that is either true or false
        boolean p = isPrime(7);   // p: 7 is prime
        boolean q = 10 % 2 == 0;  // q: 10 is even
        boolean r = 3 > 5;        // r: 3 > 5

        List<Statement> statements = List.of(
                new Statement("p", "7 is prime", p),
                new Statement("q", "10 is even", q),
                new Statement("r", "3 > 5", r),
                new Statement("~r", "3 is not greater than 5", !r),
                new Statement("p & r", "7 is prime and 3 > 5", p && r),
                new Statement("p | r", "7 is prime or 3 > 5", p || r),
                new Statement("q -> r", "if 10 is even then 3 > 5", !q || r),
                new Statement("r -> p", "if 3 > 5 then 7 is prime", !r || p),
                new Statement("p <-> q", "7 is prime iff 10 is even", p == q));

        for (Statement s : statements) {
            System.out.printf("%-8s %-27s = %s%n", s.formula(), s.english(), s.value() ? "T" : "F");
        }
        // A false hypothesis makes an implication true no matter what the conclusion says
        System.out.println("r -> p is vacuously true because r is false.");
        System.out.println("\"x + 1 = 5\" is not a proposition until x is given a value.");
    }
}

