import java.util.List;

// Build a 3-variable truth table row by row and classify each formula
public class TruthTableClassifier {
    interface Formula3 {
        boolean eval(boolean p, boolean q, boolean r);
    }

    record Formula(String name, Formula3 f) {}

    static boolean implies(boolean a, boolean b) {
        return !a || b;
    }

    static String tf(boolean b) {
        return b ? "T" : "F";
    }

    public static void main(String[] args) {
        List<Formula> formulas = List.of(
                new Formula("(p|q)->r", (p, q, r) -> implies(p || q, r)),
                new Formula("((p->q)&(q->r))->(p->r)",
                        (p, q, r) -> implies(implies(p, q) && implies(q, r), implies(p, r))),
                new Formula("p&~p", (p, q, r) -> p && !p));

        int rows = 1 << 3; // n variables give 2^n rows
        int[] trueCount = new int[formulas.size()];
        System.out.println("p q r | (p|q)->r  ((p->q)&(q->r))->(p->r)  p&~p");
        for (int i = 0; i < rows; i++) {
            // Read the row number in binary: p is the high bit, r the low bit
            boolean p = (i & 4) != 0, q = (i & 2) != 0, r = (i & 1) != 0;
            StringBuilder line = new StringBuilder(tf(p) + " " + tf(q) + " " + tf(r) + " |");
            String[] gaps = {"    ", "                 ", "              "};
            for (int k = 0; k < formulas.size(); k++) {
                boolean v = formulas.get(k).f().eval(p, q, r);
                if (v) trueCount[k]++;
                line.append(gaps[k]).append(tf(v));
            }
            System.out.println(line);
        }
        for (int k = 0; k < formulas.size(); k++) {
            String kind = trueCount[k] == rows ? "tautology"
                    : trueCount[k] == 0 ? "contradiction" : "contingency";
            System.out.println(formulas.get(k).name() + ": true in " + trueCount[k] + " of " + rows
                    + " rows -> " + kind);
        }
    }
}

