import java.util.ArrayList;
import java.util.List;

// An implication versus its converse, inverse and contrapositive
public class ImplicationVariants {
    static boolean implies(boolean p, boolean q) {
        return !p || q;
    }

    static String tf(boolean b) {
        return b ? "T" : "F";
    }

    public static void main(String[] args) {
        boolean[] values = {false, true};
        boolean contraMatches = true, converseMatches = true, inverseMatchesConverse = true;
        System.out.println("p q | p->q  q->p  ~p->~q  ~q->~p");
        for (boolean p : values) {
            for (boolean q : values) {
                boolean imp = implies(p, q);
                boolean converse = implies(q, p);
                boolean inverse = implies(!p, !q);
                boolean contra = implies(!q, !p);
                contraMatches &= imp == contra;
                converseMatches &= imp == converse;
                inverseMatchesConverse &= inverse == converse;
                String note = imp ? "" : "   <- the only row where p->q is false";
                System.out.println(tf(p) + " " + tf(q) + " |  " + tf(imp) + "     " + tf(converse) + "      "
                        + tf(inverse) + "       " + tf(contra) + note);
            }
        }
        System.out.println("contrapositive matches p->q on every row: " + contraMatches);
        System.out.println("converse matches p->q on every row:       " + converseMatches);
        System.out.println("inverse matches converse on every row:    " + inverseMatchesConverse);

        // p: "4 divides n", q: "n is even". The implication holds; its converse does not.
        List<Integer> implicationFails = new ArrayList<>();
        List<Integer> converseFails = new ArrayList<>();
        for (int n = 1; n <= 12; n++) {
            boolean p = n % 4 == 0, q = n % 2 == 0;
            if (!implies(p, q)) implicationFails.add(n);
            if (!implies(q, p)) converseFails.add(n);
        }
        System.out.println("n in 1..12 breaking \"4 | n -> n even\": " + implicationFails);
        System.out.println("n in 1..12 breaking \"n even -> 4 | n\": " + converseFails);
    }
}

