import java.util.List;

// Check equivalences by evaluating both sides on every row of the truth table
public class LogicalEquivalenceChecker {
    interface Formula3 {
        boolean eval(boolean p, boolean q, boolean r);
    }

    record Pair(String left, Formula3 a, String right, Formula3 b) {}

    static boolean implies(boolean x, boolean y) {
        return !x || y;
    }

    static String tf(boolean b) {
        return b ? "T" : "F";
    }

    // Returns null if A and B agree on all 8 rows, otherwise describes the first row that differs
    static String firstCounterexample(Formula3 a, Formula3 b) {
        for (int i = 0; i < 8; i++) {
            boolean p = (i & 4) != 0, q = (i & 2) != 0, r = (i & 1) != 0;
            boolean x = a.eval(p, q, r), y = b.eval(p, q, r);
            if (x != y) {
                return "p=" + tf(p) + " q=" + tf(q) + " r=" + tf(r) + " gives " + tf(x) + " vs " + tf(y);
            }
        }
        return null;
    }

    public static void main(String[] args) {
        // De Morgan, shown row by row first
        System.out.println("p q | ~(p&q)  ~p|~q");
        for (int i = 0; i < 4; i++) {
            boolean p = (i & 2) != 0, q = (i & 1) != 0;
            System.out.println(tf(p) + " " + tf(q) + " |    " + tf(!(p && q)) + "      " + tf(!p || !q));
        }

        List<Pair> pairs = List.of(
                new Pair("~(p&q)", (p, q, r) -> !(p && q), "~p|~q", (p, q, r) -> !p || !q),
                new Pair("~(p|q)", (p, q, r) -> !(p || q), "~p&~q", (p, q, r) -> !p && !q),
