// Direct proof of "if n is odd then n^2 is odd", traced on cases, and why cases are not enough
public class DirectProofOddSquare {
    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("Claim: if n is odd, then n^2 is odd.");
        System.out.println("Proof step: n = 2k+1  =>  n^2 = 4k^2+4k+1 = 2(2k^2+2k)+1");
        int checked = 0;
        for (int n = -5; n <= 7; n += 2) {
            int k = (n - 1) / 2;       // exact, because n - 1 is even
            int m = 2 * k * k + 2 * k; // the integer the proof says exists
            boolean matches = n * n == 2 * m + 1;
            System.out.printf("n=%3d  k=%3d  n^2=%3d = 2*%2d+1  %s%n", n, k, n * n, m, matches ? "ok" : "FAIL");
            checked++;
        }
        System.out.println(checked + " cases agree, but cases alone never prove a claim about ALL integers.");

        // A famous warning: n^2+n+41 is prime for many n in a row, then it stops
        int n = 0;
        while (isPrime(n * n + n + 41)) n++;
        int value = n * n + n + 41;
        System.out.println("n^2+n+41 is prime for n = 0.." + (n - 1) + " (" + n + " cases),");
        System.out.println("but at n = " + n + " it is " + value + " = 41*" + (value / 41) + ".");
    }
}

